def harf(not_):
    if not_ < 0 or not_ > 100:
        return 'Gecersiz'
    if not_ >= 90:
        return 'AA'
    if not_ >= 80:
        return 'BA'
    if not_ >= 70:
        return 'BB'
    if not_ >= 60:
        return 'CB'
    if not_ >= 50:
        return 'CC'
    return 'FF'

def ucgen_turu(a, b, c):
    if min(a, b, c) <= 0 or max(a, b, c) >= a + b + c - max(a, b, c):
        return 'Gecersiz'
    if a == b == c:
        return 'Eskenar'
    if a == b or b == c or a == c:
        return 'Ikizkenar'
    return 'Caliskenar'

def toplam(n):
    t = 0
    for i in range(1, n + 1):
        t += i
    return t

def faktoriyel(n):
    if n < 0:
        return -1
    s = 1
    for i in range(2, n + 1):
        s *= i
    return s

def asal_mi(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

n = int(input())
for i in range(1, n + 1):
    if i % 15 == 0:
        print('FizzBuzz')
    elif i % 3 == 0:
        print('Fizz')
    elif i % 5 == 0:
        print('Buzz')
    else:
        print(i)

n = int(input())
for i in range(1, n + 1):
    print(' ' * (n - i) + '*' * i)

def palindrom_mu(s):
    t = s.replace(' ', '').lower()
    return t == t[::-1]

def sifrele(metin, kaydir):
    sonuc = ''
    for c in metin:
        if 'a' <= c <= 'z':
            sonuc += chr((ord(c) - 97 + kaydir) % 26 + 97)
        elif 'A' <= c <= 'Z':
            sonuc += chr((ord(c) - 65 + kaydir) % 26 + 65)
        else:
            sonuc += c
    return sonuc

def anagram_mi(a, b):
    f = lambda s: sorted(s.replace(' ', '').lower())
    return f(a) == f(b)

def ikinci_buyuk(liste):
    s = sorted(set(liste), reverse=True)
    return s[1] if len(s) >= 2 else None

def tekrarsiz(liste):
    gorulen = set()
    sonuc = []
    for x in liste:
        if x not in gorulen:
            gorulen.add(x)
            sonuc.append(x)
    return sonuc

s = input().lower()
sayac = {}
for c in s:
    if c.isalpha():
        sayac[c] = sayac.get(c, 0) + 1
for harf, adet in sorted(sayac.items(), key=lambda x: (-x[1], x[0])):
    print(f'{harf}: {adet}')

def devrik(m):
    if not m:
        return []
    return [[m[i][j] for i in range(len(m))] for j in range(len(m[0]))]

def en_basarili(notlar):
    en_iyi, en_ort = None, -1
    for isim in sorted(notlar):
        l = notlar[isim]
        ort = sum(l) / len(l) if l else 0
        if ort > en_ort:
            en_iyi, en_ort = isim, ort
    return en_iyi

def iki_toplam(liste, hedef):
    for i in range(len(liste)):
        for j in range(i + 1, len(liste)):
            if liste[i] + liste[j] == hedef:
                return (i, j)
    return None

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

while True:
    satir = input()
    if satir == 'son':
        break
    try:
        a, b = satir.split()
        print(f'{float(a) / float(b):.2f}')
    except ZeroDivisionError:
        print('Sifira bolunemez')
    except ValueError:
        print('Gecersiz giris')

class Hesap:
    def __init__(self, sahip, bakiye=0):
        self.sahip = sahip
        self.bakiye = bakiye

    def yatir(self, miktar):
        if miktar <= 0:
            raise ValueError('Gecersiz miktar')
        self.bakiye += miktar

    def cek(self, miktar):
        if miktar > self.bakiye:
            raise ValueError('Yetersiz bakiye')
        self.bakiye -= miktar

    def __str__(self):
        return f'Sahip: {self.sahip}, Bakiye: {self.bakiye:.2f}'

