def sirala(liste):
    l = list(liste)
    n = len(l)
    for i in range(n):
        for j in range(n - 1 - i):
            if l[j] > l[j + 1]:
                l[j], l[j + 1] = l[j + 1], l[j]
    return l

def dengeli_mi(s):
    cift = {')': '(', ']': '[', '}': '{'}
    y = []
    for c in s:
        if c in '([{':
            y.append(c)
        elif c in cift:
            if not y or y.pop() != cift[c]:
                return False
    return not y
